import numpy as np

# Demonstrasi Mekanisme Tombstone Deletion dan Compaction Segmen
class Segment:
    def __init__(self, segment_id: int, vectors: dict):
        self.segment_id = segment_id
        self.vectors = vectors.copy() # ID -> Vector
        self.tombstones = set()       # Himpunan ID terhapus

    def soft_delete(self, vec_id: int):
        if vec_id in self.vectors:
            self.tombstones.add(vec_id)

    def search(self, query: np.ndarray, k: int = 3):
        # Kueri aktif: evaluasi hanya vektor yang BUKAN tombstone
        results = []
        for vid, v in self.vectors.items():
            if vid not in self.tombstones:
                dist = float(np.linalg.norm(v - query))
                results.append((dist, vid))
        results.sort()
        return results[:k]

def compact_segments(seg_list: list, new_seg_id: int) -> Segment:
    # Gabungkan segmen-segmen lama dan buang data bertanda tombstone secara permanen
    cleaned_vectors = {}
    for seg in seg_list:
        for vid, v in seg.vectors.items():
            if vid not in seg.tombstones:
                cleaned_vectors[vid] = v
    return Segment(new_seg_id, cleaned_vectors)

np.random.seed(42)
seg1_data = {i: np.random.randn(4) for i in range(1, 6)}
seg = Segment(segment_id=1, vectors=seg1_data)

# Tandai ID #2 dan #4 sebagai terhapus (Tombstone)
seg.soft_delete(2)
seg.soft_delete(4)

q = np.random.randn(4)
active_res = seg.search(q, k=3)

# Jalankan Compaction
compacted_seg = compact_segments([seg], new_seg_id=2)

print(f"Segmen Awal: {len(seg.vectors)} vektor, {len(seg.tombstones)} tombstone")
print(f"Hasil Kueri Aktif (ID terfilter): {[vid for _, vid in active_res]}")
print(f"Apakah ID #2 muncul di hasil kueri? {any(vid == 2 for _, vid in active_res)}")
print(f"Segmen Pasca-Compaction: {len(compacted_seg.vectors)} vektor bersih, {len(compacted_seg.tombstones)} tombstone")

import hashlib
import bisect

# Implementasi Cincin Consistent Hashing dengan Virtual Nodes untuk Sharding Vektor
class ConsistentHashRing:
    def __init__(self, nodes: list, vnodes_per_node: int = 50):
        self.vnodes_per_node = vnodes_per_node
        self.ring = []        # Hash values yang terurut
        self.vnode_map = {}   # Hash value -> Nama Node Fisik

        for node in nodes:
            self.add_node(node)

    def _hash(self, key: str) -> int:
        # Gunakan MD5 menghasilkan integer 32-bit
        return int(hashlib.md5(key.encode('utf-8')).hexdigest()[:8], 16)

    def add_node(self, node: str):
        for i in range(self.vnodes_per_node):
            vnode_key = f"{node}#vn_{i}"
            h = self._hash(vnode_key)
            bisect.insort(self.ring, h)
            self.vnode_map[h] = node

    def get_node(self, doc_id: str) -> str:
        if not self.ring:
            return None
        h = self._hash(doc_id)
        idx = bisect.bisect_right(self.ring, h)
        if idx == len(self.ring):
            idx = 0 # Wrap around ke awal cincin
        return self.vnode_map[self.ring[idx]]

nodes = ["Server_A", "Server_B", "Server_C"]
ring = ConsistentHashRing(nodes, vnodes_per_node=30)

# Uji persebaran 1000 ID dokumen vektor
doc_ids = [f"vec_doc_{i:04d}" for i in range(1000)]
distribution = {n: 0 for n in nodes}
for doc in doc_ids:
    assigned_server = ring.get_node(doc)
    distribution[assigned_server] += 1

print("Persebaran 1,000 Dokumen Vektor pada 3 Node Shard:")
for node, count in sorted(distribution.items()):
    print(f"  {node:<10}: {count} vektor ({count / 10:.1f}% beban)")
